import { useIntl } from 'react-intl';

import { BrandAvatarList, ComparisonLine, DataStateHandler } from 'components';
import { Waterfall } from 'components/Chart/Bar/Waterfall';
import { useBffData, usePageFilterApplied } from 'hooks';
import { SectionHeader } from 'pages/components/SectionHeader';
import { SharedKpis } from 'pages/enums';
import { BRAND_POWER_BOOK_PAGE_NAME } from 'pages/pillars/PortfolioBrand/BrandPowerBook/BrandPowerBook';
import { HeaderContainer } from 'pages/pillars/PortfolioBrand/BrandPowerBookExport/components/HeaderContainer';
import {
  CountryContributionChartData,
  extractLegends,
  processBrandAvatarData,
  processWaterfallData,
  WATERFALL_LAYOUT,
} from 'pages/pillars/PortfolioBrand/utils/countryContributionChartData';
import { processVariationCaptions } from 'utils/variationCaptions';

import * as S from './CountryContribution.styles';

export interface CountryContributionData extends CountryContributionChartData {
  variationCaptions: {
    title: string;
    subtitle: string;
    data: {
      value: string;
      unit_of_measure: string;
      color: string;
    }[];
  }[];
  empty?: boolean;
}

interface CountryContributionProps {
  dataTestId?: string;
}

export const CountryContribution = ({
  dataTestId,
}: CountryContributionProps = {}) => {
  const { formatMessage } = useIntl();
  const { applied } = usePageFilterApplied(BRAND_POWER_BOOK_PAGE_NAME);

  const bffData = useBffData({
    id: SharedKpis.BFF.COUNTRY_CONTRIBUTION,
    kpiGroup: 'power',
    subFilters: {
      page_filter: applied?.sub_scopes || 'All',
    },
  });

  const countriesContribution = bffData.data?.countriesContribution as
    | CountryContributionData
    | undefined;

  const { values: waterfallValues, labels: waterfallLabels } =
    processWaterfallData(countriesContribution, true);
  const legends = extractLegends(countriesContribution, {
    requireNonEmpty: true,
  });
  const comparisonData = processVariationCaptions(countriesContribution);
  const brandAvatarData = processBrandAvatarData(countriesContribution, true);

  const title = formatMessage({
    id: 'PortfolioBrand.BrandPowerBook.PowerBook.CountryContribution.title',
  });
  const subtitle = formatMessage({
    id: 'PortfolioBrand.BrandPowerBook.PowerBook.CountryContribution.subtitle',
  });

  return (
    <S.StyledCountryContributionContainer
      loading={bffData.loading}
      data-testid={dataTestId}
    >
      <HeaderContainer
        title={title}
        subtitle={subtitle}
        legends={
          legends ? (
            <S.StyledLegend>
              <SectionHeader legends={legends} dataTestId={dataTestId} />
            </S.StyledLegend>
          ) : undefined
        }
      >
        <DataStateHandler
          loading={bffData.loading}
          error={bffData.error}
          empty={countriesContribution?.empty}
          skeletonProps={{
            length: 1,
            width: '1262px',
            height: '533px',
            borderRadius: 'none',
          }}
        >
          <S.StyledWaterfallContainer>
            <Waterfall
              values={waterfallValues}
              labels={waterfallLabels}
              showLabels={false}
              size="small"
              options={{
                layout: { padding: { ...WATERFALL_LAYOUT.padding } },
                plugins: {
                  connectBars: { color: 'rgba(20, 20, 20, 0.5)' },
                  waterfallDatalabel: { decimalPlaces: 2 },
                },
              }}
              colors={WATERFALL_LAYOUT.barColors}
              decimalPlaces={1}
            />
          </S.StyledWaterfallContainer>

          <S.StyledAvatarContainer>
            <BrandAvatarList
              data={brandAvatarData}
              length={waterfallLabels.length}
              borderConfig={{ marginLeft: 0, marginRight: 0 }}
              gridConfig={{ paddingLeft: 0, paddingRight: 0 }}
            />
          </S.StyledAvatarContainer>

          <ComparisonLine
            data={comparisonData}
            gridColumnsLength={waterfallLabels.length}
            gridConfig={{ paddingLeft: 0, paddingRight: 0 }}
            borderConfig={{ marginLeft: 20, marginRight: 16 }}
          />
        </DataStateHandler>
      </HeaderContainer>
    </S.StyledCountryContributionContainer>
  );
};
